--- a/lib/media_source_owner.dart
+++ b/lib/media_source_owner.dart
@@ -4,15 +4,33 @@

 class MediaSourceOwner {
   MediaHandle? current;
+  int _request = 0;
+  bool _disposed = false;

   Future<void> start(Future<MediaHandle> Function() open) async {
-    current = await open();
+    if (_disposed) return;
+    final request = ++_request;
+    final handle = await open();
+    if (_disposed || request != _request) {
+      await handle.close();
+      return;
+    }
+
+    final previous = current;
+    current = handle;
+    await previous?.close();
   }

   Future<void> stop() async {
-    await current?.close();
+    ++_request;
+    final handle = current;
+    // Transfer ownership before asynchronous cleanup, even if close fails.
     current = null;
+    await handle?.close();
   }

-  Future<void> dispose() => stop();
+  Future<void> dispose() {
+    _disposed = true;
+    return stop();
+  }
 }
